SELECT (SELECT count(*) FROM t1) AS t1_rows, (SELECT sum(x) FROM t1) AS t1_x_sum, (SELECT sum(y) FROM t1) AS t1_y_sum, (SELECT min(x) FROM t1) AS t1_x_min, (SELECT max(x) FROM t1) AS t1_x_max, (SELECT count(*) FROM t2) AS t2_rows, (SELECT sum(x) FROM t2) AS t2_x_sum, (SELECT sum(y) FROM t2) AS t2_y_sum, (SELECT min(x) FROM t2) AS t2_x_min, (SELECT max(x) FROM t2) AS t2_x_max, (SELECT count(*) FROM sqlite_schema WHERE type='table' AND name IN ('t1','t2')) AS table_count, (SELECT count(*) FROM sqlite_schema WHERE type='index' AND name='t1i1' AND tbl_name='t1') AS index_count, (SELECT count(*) FROM pragma_index_info('t1i1') WHERE cid=0 AND name='x') AS indexed_x;